def longest_palindromic_substring(s):
    if not s:
        return ""
    n = len(s)
    result = s[0]
    for i in range(n):
        for j in (i, i + 1):
            lo, hi = i, j
            while lo >= 0 and hi < n and s[lo] == s[hi]:
                lo -= 1
                hi += 1
            candidate = s[lo + 1:hi]
            if len(candidate) > len(result):
                result = candidate
    return result

